    client.post("/reservas", json=RESERVA, headers=auth)
    r = client.get("/export", auth=("alice", "alice-pass"), headers={"X-OTP": _otp()})
    assert r.status_code == 200
    lineas = r.text.strip("\r\n").splitlines()
    assert lineas[0] == ",".join(Reserva.model_fields)
    assert len(lineas) == 2
    assert "Atlas" in lineas[1]


def test_export_sin_credenciales(client):
    assert client.get("/export").status_code == 401


def test_export_con_password_incorrecta(client):
    r = client.get("/export", auth=("alice", "mal"), headers={"X-OTP": _otp()})
    assert r.status_code == 401


def test_export_sin_otp(client):
    r = client.get("/export", auth=("alice", "alice-pass"))
    assert r.status_code == 401

